xpath.script:
(function () {
    var rows = null;
    function data() {
        if (!rows) {
            var el = document.getElementById("mtbg-phone-countries");
            if (!el) { return null; }
            rows = JSON.parse(el.textContent);
        }
        return rows;
    }
    function fill(select) {
        if (!select || select.getAttribute("data-mtbg-lazy") !== "1" || !data()) { return; }
        var current = select.value, list = document.createDocumentFragment();
        rows.forEach(function (c) {
            var option = document.createElement("option");
            option.value = c[0];
            option.dataset.name = c[1];
            option.dataset.dial = c[2];
            option.dataset.lengths = c[3];
            option.dataset.img = "/base/static/img/country_flags/" + c[0].toLowerCase() + ".png";
            option.textContent = c[4] + " " + c[1] + " (+" + c[2] + ")";
            option.selected = c[0] === current;
            list.appendChild(option);
        });
        select.replaceChildren(list);
        select.value = current;
        select.removeAttribute("data-mtbg-lazy");
    }
    function fillAll(root) {
        (root || document).querySelectorAll('select.mtbg-phone__select[data-mtbg-lazy="1"]').forEach(fill);
    }
    window.mtbgPhoneFill = fillAll;
    function onTouch(ev) {
        var field = ev.target.closest ? ev.target.closest(".mtbg-phone") : null;
        if (field) { fill(field.querySelector(".mtbg-phone__select")); }
    }
    ["pointerdown", "mousedown", "touchstart", "focusin", "keydown"].forEach(function (name) {
        document.addEventListener(name, onTouch, {capture: true, passive: true});
    });
    document.addEventListener("DOMContentLoaded", function () {
        document.querySelectorAll(".mtbg-phone").forEach(function (field) {
            var input = field.querySelector(".mtbg-phone__input");
            if (input ? input.value.trim().charAt(0) === "+" : false) { fill(field.querySelector(".mtbg-phone__select")); }
        });
    });
    window.addEventListener("load", function () {
        var later = window.requestIdleCallback || function (fn) { return setTimeout(fn, 1500); };
        later(function () { fillAll(); }, {timeout: 4000});
    });
})();
